Itt a teljesen kész main.py, amely a Vercel AI Gateway OpenAI‑kompatibilis /v1 végpontját használja az OpenAI klienssel és az „openai/gpt‑5‑pro” modellel, Repliten azonnal futtatható Flask szerverként.[1][2][3]

python
import os
from flask import Flask, request, redirect, url_for, render_template_string, session
from openai import OpenAI

# Szükséges környezeti változó Replit Secrets alatt:
# AI_GATEWAY_API_KEY = <a Vercel AI Gateway kulcsod>

AI_GATEWAY_API_KEY = os.getenv("AI_GATEWAY_API_KEY")
if not AI_GATEWAY_API_KEY:
    raise RuntimeError("Hiányzik az AI_GATEWAY_API_KEY környezeti változó (Replit Secrets-ben add meg).")

# Vercel AI Gateway OpenAI-kompatibilis végpont
client = OpenAI(
    api_key=AI_GATEWAY_API_KEY,
    base_url="https://ai-gateway.vercel.sh/v1"
)

app = Flask(__name__)
app.secret_key = os.getenv("FLASK_SECRET", "dev-secret-change-me")

HTML = """
<!doctype html>
<html>
  <head>
    <meta charset="utf-8" />
    <title>Vercel AI Gateway • GPT‑5 Pro chat</title>
    <style>
      body { font-family: system-ui, sans-serif; margin: 2rem; max-width: 800px; }
      .msg { padding: 0.75rem 1rem; border-radius: 8px; margin-bottom: 0.5rem; white-space: pre-wrap; }
      .user { background: #eef; }
      .assistant { background: #efe; }
      form { margin-top: 1rem; display: flex; gap: 0.5rem; }
      textarea { flex: 1; height: 90px; }
      button { padding: 0.5rem 1rem; }
      .error { color: #b00; margin-top: 0.5rem; }
    </style>
  </head>
  <body>
    <h1>GPT‑5 Pro chat (Vercel AI Gateway)</h1>
    <div>
      {% for m in messages %}
        {% if m.role != 'system' %}
          <div class="msg {{ 'user' if m.role=='user' else 'assistant' }}">
            <strong>{{ 'Te' if m.role=='user' else 'Asszisztens' }}:</strong>
            <div>{{ m.content }}</div>
          </div>
        {% endif %}
      {% endfor %}
    </div>
    {% if error %}
      <div class="error">{{ error }}</div>
    {% endif %}
    <form method="post" action="{{ url_for('chat') }}">
      <textarea name="message" placeholder="Írj üzenetet..." required></textarea>
      <button type="submit">Küldés</button>
    </form>
    <form method="post" action="{{ url_for('reset') }}">
      <button type="submit">Beszélgetés törlése</button>
    </form>
  </body>
</html>
"""

SYSTEM_PROMPT = "Te vagy egy segítőkész magyar nyelvű asszisztens."

def get_history():
    if "messages" not in session:
        session["messages"] = [
            {"role": "system", "content": SYSTEM_PROMPT}
        ]
    return session["messages"]

@app.route("/", methods=["GET"])
def index():
    messages = get_history()
    return render_template_string(HTML, messages=messages, error=None)

@app.route("/chat", methods=["POST"])
def chat():
    user_msg = request.form.get("message", "").strip()
    if not user_msg:
        return redirect(url_for("index"))

    messages = get_history()
    messages.append({"role": "user", "content": user_msg})
    session["messages"] = messages

    try:
        # Modell: 'openai/gpt-5-pro' (szükség esetén váltható 'openai/gpt-5'-re)
        resp = client.chat.completions.create(
            model="openai/gpt-5-pro",
            messages=messages,
            temperature=0.7,
            max_tokens=800
        )
        assistant_text = resp.choices[0].message.content
        messages.append({"role": "assistant", "content": assistant_text})
        session["messages"] = messages
        return redirect(url_for("index"))
    except Exception as e:
        # Hiba megjelenítése az oldalon
        err = f"Hiba történt: {e}"
        return render_template_string(HTML, messages=messages, error=err)

@app.route("/reset", methods=["POST"])
def reset():
    session.pop("messages", None)
    return redirect(url_for("index"))

if __name__ == "__main__":
    # Replit a PORT környezeti változót adja; alapértelmezés 8000
    port = int(os.getenv("PORT", "8000"))
    app.run(host="0.0.0.0", port=port, debug=False)


A kód az OpenAI Python klienssel hívja a Vercel AI Gateway OpenAI‑kompatibilis „/v1/chat/completions” végpontját, a modell megadását „openai/gpt‑5‑pro” formában végzi.[2][3][1]
